INSERT INTO person VALUES ('900000002','Takao Ozawa','小澤隆生','ヤフー元社長・Boost Capital運営','ヤフーの元社長。VCとPEのハイブリッドファンド「Boost Capital」を運営し、JFA(日本サッカー協会)の理事も務める。1999年にビズシークを創業して2001年に楽天に売却。2011年設立のクロコスをヤフーに売却して入社し、2022年4月から2023年9月まで、ヤフーの代表取締役社長を務めた(本人のXのプロフィールと、日本M&Aセンターの紹介による)。','x','ozarnozarn');
